WITH d AS (
  SELECT block_date, pool_label, volume_usd FROM fct_pool_daily WHERE block_date BETWEEN '2026-08-10' AND '2026-09-24'
), r AS (
  SELECT block_date, pool_label, volume_usd, max(volume_usd) OVER (PARTITION BY block_date) mx, countIf(volume_usd = max(volume_usd) OVER (PARTITION BY block_date)) OVER (PARTITION BY block_date) ties FROM d
)
SELECT countDistinct(block_date) AS total_days, countIf(pool_label = 'USDC/WETH 0.05%' AND volume_usd = mx) AS days_top, max(ties) AS max_ties FROM r
